    // v1.16.0 - PSN-Profiles paste import
    // v1.17.0 - Playnite import (RECOMMENDED - best path, user-curated statuses).
    playniteImportRowTitle:"🎯 Importuj z Playnite (zalecane)",
    playniteImportRowDesc:"Wszystkie platformy w jednym pliku JSON + Twoje statusy z Playnite mapowane 1:1",
    playniteImportTitle:"Import z Playnite",
    playniteImportStep1Title:"Jak to działa",
    playniteImportStep1Body:"Playnite to darmowy menedżer biblioteki gier który łączy Steam/Epic/GOG/Xbox/PSN/Battle.net/Origin/Uplay w jedną bibliotekę. Twoje statusy (Beaten, Playing, Plan to Play, Abandoned) zostaną przeniesione 1:1, bez zgadywania.",
    playniteImportStep1Step1:"1. Otwórz <strong>Playnite</strong> (Windows). Jeśli nie masz: <a href='https://playnite.link' target='_blank'>playnite.link</a> (darmowe, open source)",
    playniteImportStep1Step2:"2. Zainstaluj rozszerzenie <strong>\"Library Exporter\"</strong>: menu Add-ons → Browse → wyszukaj \"Library Exporter\" → Install",
    playniteImportStep1Step3:"3. Po instalacji: menu <strong>Extensions</strong> → Library Exporter → wybierz format <strong>JSON</strong>",
    playniteImportStep1Step4:"4. Zapisz plik <code>.json</code> z całą biblioteką",
    playniteImportStep1Step5:"5. Wgraj plik poniżej i kliknij Dalej. <em>📱 Z telefonu? Najlepiej zsynchronizuj plik przez chmurę (Drive, Dropbox), pobierz i wgraj w app.</em>",
    playniteImportPasteLabel:"Lub wklej zawartość JSON tutaj:",
