    psnImportRowTitle:"📥 Importuj z PSN-Profiles",
    psnImportRowDesc:"Wczytaj swoją bibliotekę PSN przez psnprofiles.com",
    psnImportTitle:"Import z PSN-Profiles",
    psnImportStep1Title:"Jak to działa",
    psnImportStep1Body:"PSN-Profiles to publiczny mirror Twojej biblioteki PSN. Nie ma wbudowanego eksportu CSV, więc skopiujesz tabelę bezpośrednio z telefonu.",
    psnImportStep1Step1:"1. Otwórz <strong>Chrome</strong> i wejdź na <strong>psnprofiles.com</strong>, utwórz darmowe konto (jeśli nie masz) i podlinkuj PSN ID (sync ~5 min)",
    psnImportStep1Step2:"2. Wejdź bezpośrednio na <strong>psnprofiles.com/TWOJ-PSN-ID/games</strong> (NIE profil ogólny, bo strona <code>/games</code> ma czystą tabelę bez sidebar'ów z reklamami)",
    psnImportStep1Step3:"3. Przewiń <strong>na sam dół tabelki gier</strong> (żeby załadować wszystkie) → naciśnij i przytrzymaj tytuł → <strong>\"Zaznacz wszystko\"</strong>. Parser automatycznie odfiltruje sekcje typu \"Recommended/Sponsored\" jeśli się dostaną.",
    psnImportStep1Step4:"4. Tap <strong>\"Kopiuj\"</strong> (Chrome skopiuje tabelę z tabulatorami między kolumnami, a parser to rozumie)",
    psnImportStep1Step5:"5. Wróć tutaj → long-press w polu tekstowym poniżej → <strong>Wklej</strong> → Dalej. <br><em>📱 iPhone/Safari? Działa tak samo (Safari kopiuje komórka po komórce, parser to obsługuje). 💻 PC? Ctrl+S → zapisz HTML → wgraj plik powyżej.</em>",
    psnImportPasteLabel:"Wklej skopiowaną tabelę z PSN-Profiles tutaj:",
    psnImportPastePh:"Game\\tPlatform\\tTrophies\\tHours\\tProgress\\nGod of War Ragnarök\\tPS5\\t36/36\\t18\\t100%",
