    // v1.16.1 - Steam paste import (via steamcommunity.com page source)
    steamImportRowTitle:"⚙️ Importuj ze Steam",
    steamImportRowDesc:"Wczytaj swoją bibliotekę Steam (paste z page source)",
    steamImportTitle:"Import ze Steam",
    steamImportStep1Title:"Jak to działa",
    steamImportStep1Body:"Steam Web API jest CORS-blocked, więc używamy page-source z publicznego profilu (biblioteka musi być <strong>publiczna</strong>).",
    steamImportStep1Step1:"1. Otwórz <strong>Chrome</strong> i wpisz w pasku adresu: <code>view-source:steamcommunity.com/id/TWOJ-ID/games?tab=all</code> (na PC po prostu Ctrl+U na stronie Games)",
    steamImportStep1Step2:"2. Po wczytaniu zobaczysz surowy kod HTML/JS strony",
    steamImportStep1Step3:"3. Long-press tekst → tap <strong>\"Find in page\"</strong> (3-kropki menu) → wpisz <strong>rgGames</strong>, przewinie do <code>var rgGames = [...]</code>",
    steamImportStep1Step4:"4. Long-press w okolicy → \"Zaznacz wszystko\" → \"Kopiuj\" (parser sam wyfiltruje rgGames JSON spośród całego HTML)",
    steamImportStep1Step5:"5. Wklej w polu poniżej i kliknij Dalej. <em>💻 PC: Ctrl+U → Ctrl+F \"rgGames\" → zaznacz <code>[...]</code> → wklej tu.</em>",
    steamImportPasteLabel:"Wklej zawartość rgGames tutaj:",
