    xboxImportStep1Body:"TrueAchievements to publiczny mirror Xbox. <strong>CSV Export wymaga TA Pro</strong> ($5/rok), ale darmowi użytkownicy mogą po prostu skopiować tabelkę z telefonu, a parser to obsługuje.",
