    playniteImportRowDesc:"All platforms in one JSON file + your Playnite statuses mapped 1:1",
    playniteImportTitle:"Import from Playnite",
    playniteImportStep1Title:"How it works",
    playniteImportStep1Body:"Playnite is a free game library manager that aggregates Steam/Epic/GOG/Xbox/PSN/Battle.net/Origin/Uplay into one library. Your statuses (Beaten, Playing, Plan to Play, Abandoned) carry over 1:1, no guesswork.",
    playniteImportStep1Step1:"1. Open <strong>Playnite</strong> (Windows). Don't have it? <a href='https://playnite.link' target='_blank'>playnite.link</a> (free, open source)",
    playniteImportStep1Step2:"2. Install <strong>\"Library Exporter\"</strong> extension: Add-ons menu → Browse → search \"Library Exporter\" → Install",
    playniteImportStep1Step3:"3. After install: <strong>Extensions</strong> menu → Library Exporter → choose <strong>JSON</strong> format",
    playniteImportStep1Step4:"4. Save the <code>.json</code> file with your whole library",
    playniteImportStep1Step5:"5. Upload the file below and click Next. <em>📱 From phone? Sync the file via cloud (Drive, Dropbox), download and upload here.</em>",
    playniteImportPasteLabel:"Or paste JSON content here:",
    playniteImportPastePh:"[{\"Name\":\"The Witcher 3\",\"Source\":{\"Name\":\"Steam\"},\"Playtime\":360000,\"CompletionStatus\":{\"Name\":\"Beaten\"}},...]",
    playniteImportNextBtn:"Next →",
    playniteImportBackBtn:"← Back",
    playniteImportEmpty:"No games found. Make sure the JSON is from Playnite Library Exporter.",
    playniteImportPreviewTitle:"Found {n} {gw}",
    playniteImportPreviewSub:"Statuses from Playnite (Beaten/Playing/etc.) auto-mapped. Click any status badge to change.",
    playniteImportCommitBtn:"+ Add selected ({n})",
    playniteImportSuccess:"✓ Imported {n} {gw} from Playnite",
    playniteImportOpenSite:"Open playnite.link →",
    psnImportRowTitle:"📥 Import from PSN-Profiles",
    psnImportRowDesc:"Load your PSN library via psnprofiles.com",
    psnImportTitle:"Import from PSN-Profiles",
    psnImportStep1Title:"How it works",
    psnImportStep1Body:"PSN-Profiles is a public mirror of your PSN library. There's no built-in CSV export, so you'll copy the table directly from your phone.",
    psnImportStep1Step1:"1. Open <strong>Chrome</strong> and go to <strong>psnprofiles.com</strong>, create a free account (if you don't have one) and link your PSN ID (sync ~5 min)",
    psnImportStep1Step2:"2. Go directly to <strong>psnprofiles.com/YOUR-PSN-ID/games</strong> (NOT the general profile: the <code>/games</code> page has a clean table without sidebar ads/recommendations)",
    psnImportStep1Step3:"3. Scroll <strong>to the very bottom of the games table</strong> (so all games load) → long-press a title → <strong>\"Select all\"</strong>. Parser auto-filters \"Recommended/Sponsored\" sections if they sneak in.",
    psnImportStep1Step4:"4. Tap <strong>\"Copy\"</strong> (Chrome copies the table with tabs between columns, which our parser handles)",
    psnImportStep1Step5:"5. Come back here → long-press the textarea below → <strong>Paste</strong> → Next. <br><em>📱 iPhone/Safari? Works the same (Safari copies cell-per-line, the parser handles it). 💻 Desktop? Ctrl+S on the Games page → save as HTML → upload file above.</em>",
    psnImportPasteLabel:"Paste the copied PSN-Profiles table here:",
    psnImportPastePh:"Game\\tPlatform\\tTrophies\\tHours\\tProgress\\nGod of War Ragnarök\\tPS5\\t36/36\\t18\\t100%",
