    // v1.16.1 - Steam paste import
    steamImportRowTitle:"⚙️ Import from Steam",
    steamImportRowDesc:"Load your Steam library (paste from page source)",
    steamImportTitle:"Import from Steam",
    steamImportStep1Title:"How it works",
    steamImportStep1Body:"Steam Web API is CORS-blocked, so we use page-source from your public profile (library must be <strong>public</strong>).",
    steamImportStep1Step1:"1. Open <strong>Chrome</strong> and type in the address bar: <code>view-source:steamcommunity.com/id/YOUR-ID/games?tab=all</code> (desktop: just Ctrl+U on the Games page)",
    steamImportStep1Step2:"2. After loading, you'll see the raw HTML/JS code of the page",
    steamImportStep1Step3:"3. Long-press text → tap <strong>\"Find in page\"</strong> (3-dot menu) → type <strong>rgGames</strong>, it'll scroll to <code>var rgGames = [...]</code>",
    steamImportStep1Step4:"4. Long-press → \"Select all\" → \"Copy\" (parser will extract the rgGames JSON from the full HTML on its own)",
    steamImportStep1Step5:"5. Paste in the field below and click Next. <em>💻 Desktop: Ctrl+U → Ctrl+F \"rgGames\" → select <code>[...]</code> → paste here.</em>",
    steamImportPasteLabel:"Paste rgGames content here:",
    steamImportPastePh:"[{\"appid\":1245620,\"name\":\"ELDEN RING\",\"playtime_forever\":5840},...]",
