    psnImportTitle:"Importar de PSN-Profiles",
    psnImportStep1Title:"Cómo funciona",
    psnImportStep1Body:"PSN-Profiles es un mirror público de tu biblioteca PSN. No tiene exportación CSV integrada, así que copiarás la tabla directamente desde tu móvil.",
    psnImportStep1Step1:"1. Abre <strong>Chrome</strong> y entra en <strong>psnprofiles.com</strong>, crea una cuenta gratuita (si no tienes) y enlaza tu PSN ID (sync ~5 min)",
    psnImportStep1Step2:"2. Ve directamente a <strong>psnprofiles.com/TU-PSN-ID/games</strong> (NO al perfil general: la página <code>/games</code> tiene tabla limpia sin sidebar de anuncios)",
    psnImportStep1Step3:"3. Desplázate <strong>hasta el final de la tabla</strong> (para cargar todos los juegos) → mantén pulsado un título → <strong>\"Seleccionar todo\"</strong>. El parser filtra automáticamente secciones \"Recommended/Sponsored\" si aparecen.",
    psnImportStep1Step4:"4. Pulsa <strong>\"Copiar\"</strong> (Chrome copia la tabla con tabuladores entre columnas, y nuestro parser lo entiende)",
    psnImportStep1Step5:"5. Vuelve aquí → mantén pulsado el campo de texto de abajo → <strong>Pegar</strong> → Siguiente. <br><em>📱 ¿iPhone/Safari? Funciona igual (Safari copia celda por línea, el parser lo gestiona). 💻 ¿En PC? Ctrl+S en la página Games → guardar como HTML → subir archivo arriba.</em>",
