    steamImportStep1Body:"La API web de Steam está bloqueada por CORS, así que usamos el código fuente del perfil público (biblioteca debe ser <strong>pública</strong>).",
    steamImportStep1Step1:"1. Abre <strong>Chrome</strong> y escribe en la barra de direcciones: <code>view-source:steamcommunity.com/id/TU-ID/games?tab=all</code> (PC: simplemente Ctrl+U en la página Games)",
    steamImportStep1Step2:"2. Tras cargar, verás el código HTML/JS de la página",
    steamImportStep1Step3:"3. Mantén pulsado el texto → pulsa <strong>\"Buscar en página\"</strong> (menú 3 puntos) → escribe <strong>rgGames</strong>, saltará a <code>var rgGames = [...]</code>",
    steamImportStep1Step4:"4. Mantén pulsado → \"Seleccionar todo\" → \"Copiar\" (el parser extraerá el JSON rgGames del HTML completo)",
    steamImportStep1Step5:"5. Pega en el campo de abajo y haz clic en Siguiente. <em>💻 PC: Ctrl+U → Ctrl+F \"rgGames\" → selecciona <code>[...]</code> → pega aquí.</em>",
