    playniteImportRowDesc:"Alle Plattformen in einer JSON-Datei + deine Playnite-Status 1:1 übernommen",
    playniteImportTitle:"Aus Playnite importieren",
    playniteImportStep1Title:"So funktioniert's",
    playniteImportStep1Body:"Playnite ist ein kostenloser Bibliotheksmanager, der Steam/Epic/GOG/Xbox/PSN/Battle.net/Origin/Uplay in einer Bibliothek bündelt. Deine Status (Beaten, Playing, Plan to Play, Abandoned) werden 1:1 übernommen, ohne Raten.",
    playniteImportStep1Step1:"1. Öffne <strong>Playnite</strong> (Windows). Noch nicht installiert? <a href='https://playnite.link' target='_blank'>playnite.link</a> (kostenlos, Open Source)",
    playniteImportStep1Step2:"2. Installiere die Erweiterung <strong>\"Library Exporter\"</strong>: Menü Add-ons → Browse → nach \"Library Exporter\" suchen → Install",
    playniteImportStep1Step3:"3. Nach der Installation: Menü <strong>Extensions</strong> → Library Exporter → Format <strong>JSON</strong> wählen",
    playniteImportStep1Step4:"4. Speichere die <code>.json</code>-Datei mit deiner ganzen Bibliothek",
    playniteImportStep1Step5:"5. Lade die Datei unten hoch und tippe auf Weiter. <em>📱 Vom Handy? Synchronisiere die Datei über die Cloud (Drive, Dropbox), lade sie herunter und hier hoch.</em>",
    playniteImportPasteLabel:"Oder füge den JSON-Inhalt hier ein:",
    playniteImportPastePh:"[{\"Name\":\"The Witcher 3\",\"Source\":{\"Name\":\"Steam\"},\"Playtime\":360000,\"CompletionStatus\":{\"Name\":\"Beaten\"}},...]",
    playniteImportNextBtn:"Weiter →",
