    playniteImportSuccess:"✓ {n} {gw} aus Playnite importiert",
    playniteImportOpenSite:"playnite.link öffnen →",
    psnImportRowTitle:"📥 Aus PSN-Profiles importieren",
    psnImportRowDesc:"Lade deine PSN-Bibliothek über psnprofiles.com",
    psnImportTitle:"Aus PSN-Profiles importieren",
    psnImportStep1Title:"So funktioniert's",
    psnImportStep1Body:"PSN-Profiles ist ein öffentliches Abbild deiner PSN-Bibliothek. Es gibt keinen eingebauten CSV-Export, daher kopierst du die Tabelle direkt vom Handy.",
    psnImportStep1Step1:"1. Öffne <strong>Chrome</strong> und geh auf <strong>psnprofiles.com</strong>, erstelle ein kostenloses Konto (falls nötig) und verknüpfe deine PSN-ID (Sync ~5 Min.)",
    psnImportStep1Step2:"2. Geh direkt auf <strong>psnprofiles.com/DEINE-PSN-ID/games</strong> (NICHT das allgemeine Profil: Die Seite <code>/games</code> hat eine saubere Tabelle ohne Werbung und Empfehlungen in der Seitenleiste)",
    psnImportStep1Step3:"3. Scrolle <strong>ganz ans Ende der Spieltabelle</strong> (damit alle Spiele laden) → halte einen Titel gedrückt → <strong>\"Alles auswählen\"</strong>. Der Parser filtert Bereiche wie \"Recommended/Sponsored\" automatisch heraus.",
    psnImportStep1Step4:"4. Tippe auf <strong>\"Kopieren\"</strong> (Chrome kopiert die Tabelle mit Tabs zwischen den Spalten, das versteht unser Parser)",
    psnImportStep1Step5:"5. Komm hierher zurück → halte das Textfeld unten gedrückt → <strong>Einfügen</strong> → Weiter. <br><em>📱 iPhone/Safari? Funktioniert genauso (Safari kopiert eine Zelle pro Zeile, der Parser kommt damit klar). 💻 Desktop? Strg+S auf der Spieleseite → als HTML speichern → Datei oben hochladen.</em>",
    psnImportPasteLabel:"Füge die kopierte PSN-Profiles-Tabelle hier ein:",
    psnImportPastePh:"Game\\tPlatform\\tTrophies\\tHours\\tProgress\\nGod of War Ragnarök\\tPS5\\t36/36\\t18\\t100%",
