    steamImportStep1Title:"So funktioniert's",
    steamImportStep1Body:"Die Steam Web API ist per CORS blockiert, daher nutzen wir den Seitenquelltext deines öffentlichen Profils (die Bibliothek muss <strong>öffentlich</strong> sein).",
    steamImportStep1Step1:"1. Öffne <strong>Chrome</strong> und gib in die Adressleiste ein: <code>view-source:steamcommunity.com/id/DEINE-ID/games?tab=all</code> (Desktop: einfach Strg+U auf der Spieleseite)",
    steamImportStep1Step2:"2. Nach dem Laden siehst du den rohen HTML/JS-Code der Seite",
    steamImportStep1Step3:"3. Halte Text gedrückt → tippe auf <strong>\"Auf Seite suchen\"</strong> (Drei-Punkte-Menü) → gib <strong>rgGames</strong> ein, es springt zu <code>var rgGames = [...]</code>",
    steamImportStep1Step4:"4. Gedrückt halten → \"Alles auswählen\" → \"Kopieren\" (der Parser holt sich das rgGames-JSON selbst aus dem ganzen HTML)",
    steamImportStep1Step5:"5. Füge es unten ein und tippe auf Weiter. <em>💻 Desktop: Strg+U → Strg+F \"rgGames\" → <code>[...]</code> markieren → hier einfügen.</em>",
