    wizard2Body:"L'appli affiche tous les montants dans la devise choisie. Pas de conversion : saisis les prix directement dans cette devise. Tu peux la changer à tout moment dans les réglages.",
    wizard2Btn:"Suivant →",
    wizard3Title:"Afficher des jeux d'exemple ?",
    wizard3Body:"On peut ajouter quelques jeux d'exemple (Spider-Man 2, Elden Ring, GTA V) pour te montrer comment marche l'appli : finances, stats, succès. Ou tu commences avec une bibliothèque vide et ajoutes tes propres jeux tout de suite.",
    wizard3Yes:"Afficher les exemples",
    wizard3No:"Commencer avec une bibliothèque vide",
    wizard4Title:"Comment marche PS5 Vault",
    wizard4Body:"PS5 Vault ne se connecte pas à ton compte PSN : la collection est à toi et reste sur ton téléphone. Ajoute tes jeux de trois façons : en tapant le titre (jaquette, genre et date viennent de la base RAWG), en scannant le code-barres de la boîte ou en important toute ta bibliothèque Steam, PSN, Xbox ou Playnite (Réglages). Tu notes toi-même les heures et les prix.",
