    playniteImportRowTitle:"🎯 Importer depuis Playnite (recommandé)",
    playniteImportRowDesc:"Toutes les plateformes dans un fichier JSON + tes statuts Playnite repris tels quels",
    playniteImportTitle:"Importer depuis Playnite",
    playniteImportStep1Title:"Comment ça marche",
    playniteImportStep1Body:"Playnite est un gestionnaire de bibliothèque gratuit qui regroupe Steam/Epic/GOG/Xbox/PSN/Battle.net/Origin/Uplay en une seule bibliothèque. Tes statuts (Beaten, Playing, Plan to Play, Abandoned) sont repris tels quels, sans approximation.",
    playniteImportStep1Step1:"1. Ouvre <strong>Playnite</strong> (Windows). Pas encore installé ? <a href='https://playnite.link' target='_blank'>playnite.link</a> (gratuit, open source)",
    playniteImportStep1Step2:"2. Installe l'extension <strong>\"Library Exporter\"</strong> : menu Add-ons → Browse → cherche \"Library Exporter\" → Install",
    playniteImportStep1Step3:"3. Après l'installation : menu <strong>Extensions</strong> → Library Exporter → choisis le format <strong>JSON</strong>",
    playniteImportStep1Step4:"4. Enregistre le fichier <code>.json</code> avec toute ta bibliothèque",
    playniteImportStep1Step5:"5. Envoie le fichier ci-dessous et touche Suivant. <em>📱 Depuis ton téléphone ? Synchronise le fichier via le cloud (Drive, Dropbox), télécharge-le puis envoie-le ici.</em>",
    playniteImportPasteLabel:"Ou colle le contenu JSON ici :",
    playniteImportPastePh:"[{\"Name\":\"The Witcher 3\",\"Source\":{\"Name\":\"Steam\"},\"Playtime\":360000,\"CompletionStatus\":{\"Name\":\"Beaten\"}},...]",
    playniteImportNextBtn:"Suivant →",
    playniteImportBackBtn:"← Retour",
    playniteImportEmpty:"Aucun jeu trouvé. Vérifie que le JSON vient de Playnite Library Exporter.",
    playniteImportPreviewTitle:"{n} {gw} trouvés",
    playniteImportPreviewSub:"Statuts Playnite (Beaten/Playing, etc.) associés automatiquement. Touche un badge de statut pour le changer.",
    playniteImportCommitBtn:"+ Ajouter la sélection ({n})",
    playniteImportSuccess:"✓ {n} {gw} importés depuis Playnite",
    playniteImportOpenSite:"Ouvrir playnite.link →",
    psnImportRowTitle:"📥 Importer depuis PSN-Profiles",
    psnImportRowDesc:"Charge ta bibliothèque PSN via psnprofiles.com",
    psnImportTitle:"Importer depuis PSN-Profiles",
    psnImportStep1Title:"Comment ça marche",
    psnImportStep1Body:"PSN-Profiles est un miroir public de ta bibliothèque PSN. Il n'y a pas d'export CSV intégré, tu vas donc copier le tableau directement depuis ton téléphone.",
    psnImportStep1Step1:"1. Ouvre <strong>Chrome</strong> et va sur <strong>psnprofiles.com</strong>, crée un compte gratuit (si besoin) et associe ton ID PSN (synchro ~5 min)",
    psnImportStep1Step2:"2. Va directement sur <strong>psnprofiles.com/TON-ID-PSN/games</strong> (PAS le profil général : la page <code>/games</code> a un tableau propre sans pubs ni recommandations sur le côté)",
    psnImportStep1Step3:"3. Fais défiler <strong>jusqu'en bas du tableau des jeux</strong> (pour tout charger) → appui long sur un titre → <strong>\"Tout sélectionner\"</strong>. Le parseur filtre automatiquement les sections \"Recommended/Sponsored\".",
    psnImportStep1Step4:"4. Touche <strong>\"Copier\"</strong> (Chrome copie le tableau avec des tabulations entre les colonnes, notre parseur s'en charge)",
    psnImportStep1Step5:"5. Reviens ici → appui long sur le champ ci-dessous → <strong>Coller</strong> → Suivant. <br><em>📱 iPhone/Safari ? Pareil (Safari copie une cellule par ligne, le parseur gère). 💻 Ordinateur ? Ctrl+S sur la page des jeux → enregistrer en HTML → envoie le fichier ci-dessus.</em>",
    psnImportPasteLabel:"Colle ici le tableau PSN-Profiles copié :",
    psnImportPastePh:"Game\\tPlatform\\tTrophies\\tHours\\tProgress\\nGod of War Ragnarök\\tPS5\\t36/36\\t18\\t100%",
    psnImportNextBtn:"Suivant →",
    psnImportBackBtn:"← Retour",
    psnImportEmpty:"Aucun jeu trouvé. Vérifie le format CSV.",
    psnImportPreviewTitle:"{n} {gw} trouvés",
    psnImportPreviewSub:"Recherche des données sur RAWG (jaquettes, genres). Décoche les jeux que tu ne veux pas importer.",
    psnImportMatching:"⏳ Recherche…",
    psnImportFound:"✓ Trouvé",
    psnImportNoMatch:"⚠️ Pas de données RAWG : seul le titre sera importé",
    psnImportDup:"↻ Déjà dans la bibliothèque",
    psnImportCommitBtn:"+ Ajouter la sélection ({n})",
    psnImportCommitting:"⏳ Ajout en cours…",
    psnImportSuccess:"✓ {n} {gw} importés depuis PSN-Profiles",
    psnImportNothing:"Rien de sélectionné",
    psnImportOpenSite:"Ouvrir psnprofiles.com →",
    steamImportRowTitle:"⚙️ Importer depuis Steam",
    steamImportRowDesc:"Charge ta bibliothèque Steam (collage depuis le code source de la page)",
    steamImportTitle:"Importer depuis Steam",
    steamImportStep1Title:"Comment ça marche",
    steamImportStep1Body:"L'API Web de Steam est bloquée par CORS, on utilise donc le code source de ton profil public (la bibliothèque doit être <strong>publique</strong>).",
    steamImportStep1Step1:"1. Ouvre <strong>Chrome</strong> et tape dans la barre d'adresse : <code>view-source:steamcommunity.com/id/TON-ID/games?tab=all</code> (ordinateur : simplement Ctrl+U sur la page des jeux)",
    steamImportStep1Step2:"2. Une fois chargé, tu verras le code HTML/JS brut de la page",
    steamImportStep1Step3:"3. Appui long sur le texte → touche <strong>\"Rechercher dans la page\"</strong> (menu à 3 points) → tape <strong>rgGames</strong>, ça défile jusqu'à <code>var rgGames = [...]</code>",
    steamImportStep1Step4:"4. Appui long → \"Tout sélectionner\" → \"Copier\" (le parseur extrait tout seul le JSON rgGames du HTML complet)",
