    wizard2Btn:"Avanti →",
    wizard3Title:"Mostrare giochi di esempio?",
    wizard3Body:"Possiamo aggiungere alcuni giochi di esempio (Spider-Man 2, Elden Ring, GTA V) per mostrarti come funziona l'app: finanze, statistiche, obiettivi. Oppure inizia con una libreria vuota e aggiungi subito i tuoi giochi.",
    wizard3Yes:"Mostra gli esempi",
    wizard3No:"Inizia con la libreria vuota",
    wizard4Title:"Come funziona PS5 Vault",
    wizard4Body:"PS5 Vault non si collega al tuo account PSN: la collezione è tua e resta sul telefono. Aggiungi i giochi in tre modi: scrivendo il titolo (copertina, genere e data arrivano dal database RAWG), scansionando il codice a barre della confezione o importando tutta la libreria da Steam, PSN, Xbox o Playnite (Impostazioni). Ore e prezzi li inserisci tu.",
