    playniteImportRowTitle:"🎯 Importa da Playnite (consigliato)",
    playniteImportRowDesc:"Tutte le piattaforme in un file JSON + i tuoi stati di Playnite riportati 1:1",
    playniteImportTitle:"Importa da Playnite",
    playniteImportStep1Title:"Come funziona",
    playniteImportStep1Body:"Playnite è un gestore di librerie gratuito che riunisce Steam/Epic/GOG/Xbox/PSN/Battle.net/Origin/Uplay in un'unica libreria. I tuoi stati (Beaten, Playing, Plan to Play, Abandoned) vengono riportati 1:1, senza indovinare.",
    playniteImportStep1Step1:"1. Apri <strong>Playnite</strong> (Windows). Non ce l'hai? <a href='https://playnite.link' target='_blank'>playnite.link</a> (gratuito, open source)",
    playniteImportStep1Step2:"2. Installa l'estensione <strong>\"Library Exporter\"</strong>: menu Add-ons → Browse → cerca \"Library Exporter\" → Install",
    playniteImportStep1Step3:"3. Dopo l'installazione: menu <strong>Extensions</strong> → Library Exporter → scegli il formato <strong>JSON</strong>",
    playniteImportStep1Step4:"4. Salva il file <code>.json</code> con tutta la tua libreria",
    playniteImportStep1Step5:"5. Carica il file qui sotto e tocca Avanti. <em>📱 Dal telefono? Sincronizza il file nel cloud (Drive, Dropbox), scaricalo e caricalo qui.</em>",
    playniteImportPasteLabel:"Oppure incolla qui il contenuto JSON:",
    playniteImportPastePh:"[{\"Name\":\"The Witcher 3\",\"Source\":{\"Name\":\"Steam\"},\"Playtime\":360000,\"CompletionStatus\":{\"Name\":\"Beaten\"}},...]",
    playniteImportNextBtn:"Avanti →",
    playniteImportBackBtn:"← Indietro",
    playniteImportEmpty:"Nessun gioco trovato. Controlla che il JSON provenga da Playnite Library Exporter.",
    playniteImportPreviewTitle:"Trovati {n} {gw}",
    playniteImportPreviewSub:"Stati di Playnite (Beaten/Playing ecc.) abbinati in automatico. Tocca un'etichetta di stato per cambiarla.",
    playniteImportCommitBtn:"+ Aggiungi selezionati ({n})",
    playniteImportSuccess:"✓ Importati {n} {gw} da Playnite",
    playniteImportOpenSite:"Apri playnite.link →",
    psnImportRowTitle:"📥 Importa da PSN-Profiles",
    psnImportRowDesc:"Carica la tua libreria PSN tramite psnprofiles.com",
    psnImportTitle:"Importa da PSN-Profiles",
    psnImportStep1Title:"Come funziona",
    psnImportStep1Body:"PSN-Profiles è una copia pubblica della tua libreria PSN. Non c'è un export CSV integrato, quindi copierai la tabella direttamente dal telefono.",
    psnImportStep1Step1:"1. Apri <strong>Chrome</strong> e vai su <strong>psnprofiles.com</strong>, crea un account gratuito (se non ce l'hai) e collega il tuo ID PSN (sincronizzazione ~5 min)",
    psnImportStep1Step2:"2. Vai direttamente su <strong>psnprofiles.com/TUO-ID-PSN/games</strong> (NON il profilo generale: la pagina <code>/games</code> ha una tabella pulita senza pubblicità e consigli laterali)",
    psnImportStep1Step3:"3. Scorri <strong>fino in fondo alla tabella dei giochi</strong> (così si caricano tutti) → tieni premuto un titolo → <strong>\"Seleziona tutto\"</strong>. Il parser filtra in automatico le sezioni \"Recommended/Sponsored\".",
    psnImportStep1Step4:"4. Tocca <strong>\"Copia\"</strong> (Chrome copia la tabella con le tabulazioni tra le colonne, il nostro parser le gestisce)",
    psnImportStep1Step5:"5. Torna qui → tieni premuto il campo qui sotto → <strong>Incolla</strong> → Avanti. <br><em>📱 iPhone/Safari? Funziona uguale (Safari copia una cella per riga, il parser la gestisce). 💻 Computer? Ctrl+S sulla pagina dei giochi → salva come HTML → carica il file qui sopra.</em>",
    psnImportPasteLabel:"Incolla qui la tabella di PSN-Profiles copiata:",
    psnImportPastePh:"Game\\tPlatform\\tTrophies\\tHours\\tProgress\\nGod of War Ragnarök\\tPS5\\t36/36\\t18\\t100%",
    psnImportNextBtn:"Avanti →",
    psnImportBackBtn:"← Indietro",
    psnImportEmpty:"Nessun gioco trovato. Controlla il formato CSV.",
    psnImportPreviewTitle:"Trovati {n} {gw}",
    psnImportPreviewSub:"Cerco i dati su RAWG (copertine, generi). Togli la spunta ai giochi che non vuoi importare.",
    psnImportMatching:"⏳ Ricerca…",
    psnImportFound:"✓ Trovato",
    psnImportNoMatch:"⚠️ Nessun dato RAWG: verrà importato solo il titolo",
    psnImportDup:"↻ Già nella libreria",
    psnImportCommitBtn:"+ Aggiungi selezionati ({n})",
    psnImportCommitting:"⏳ Aggiunta in corso…",
    psnImportSuccess:"✓ Importati {n} {gw} da PSN-Profiles",
    psnImportNothing:"Nessuna selezione",
    psnImportOpenSite:"Apri psnprofiles.com →",
    steamImportRowTitle:"⚙️ Importa da Steam",
    steamImportRowDesc:"Carica la tua libreria Steam (incollando dal sorgente della pagina)",
    steamImportTitle:"Importa da Steam",
    steamImportStep1Title:"Come funziona",
    steamImportStep1Body:"La Web API di Steam è bloccata dal CORS, quindi usiamo il sorgente della pagina del tuo profilo pubblico (la libreria deve essere <strong>pubblica</strong>).",
    steamImportStep1Step1:"1. Apri <strong>Chrome</strong> e scrivi nella barra degli indirizzi: <code>view-source:steamcommunity.com/id/TUO-ID/games?tab=all</code> (computer: basta Ctrl+U sulla pagina dei giochi)",
    steamImportStep1Step2:"2. Dopo il caricamento vedrai il codice HTML/JS grezzo della pagina",
    steamImportStep1Step3:"3. Tieni premuto il testo → tocca <strong>\"Trova nella pagina\"</strong> (menu a 3 puntini) → scrivi <strong>rgGames</strong>, scorrerà fino a <code>var rgGames = [...]</code>",
    steamImportStep1Step4:"4. Tieni premuto → \"Seleziona tutto\" → \"Copia\" (il parser estrae da solo il JSON rgGames dall'HTML completo)",
    steamImportStep1Step5:"5. Incolla nel campo qui sotto e tocca Avanti. <em>💻 Computer: Ctrl+U → Ctrl+F \"rgGames\" → seleziona <code>[...]</code> → incolla qui.</em>",
    steamImportPasteLabel:"Incolla qui il contenuto di rgGames:",
    steamImportPastePh:"[{\"appid\":1245620,\"name\":\"ELDEN RING\",\"playtime_forever\":5840},...]",
    steamImportNextBtn:"Avanti →",
    steamImportBackBtn:"← Indietro",
    steamImportEmpty:"Nessun gioco trovato. Controlla il formato incollato (JSON rgGames, array semplice o elenco di titoli riga per riga).",
    steamImportPreviewTitle:"Trovati {n} {gw}",
    steamImportPreviewSub:"Cerco i dati su RAWG (copertine, generi). Togli la spunta ai giochi che non vuoi importare.",
    steamImportCommitBtn:"+ Aggiungi selezionati ({n})",
    steamImportSuccess:"✓ Importati {n} {gw} da Steam",
    steamImportOpenSite:"Apri steamcommunity.com →",
    xboxImportRowTitle:"🟢 Importa da Xbox (TrueAchievements)",
    xboxImportRowDesc:"Carica la tua libreria Xbox tramite trueachievements.com",
    xboxImportTitle:"Importa da TrueAchievements",
    xboxImportStep1Title:"Come funziona",
    xboxImportStep1Body:"TrueAchievements è una copia pubblica di Xbox. <strong>L'export CSV richiede TA Pro</strong> (5 $/anno), ma chi usa la versione gratuita può semplicemente copiare la tabella dal telefono, il nostro parser la gestisce.",
    xboxImportStep1Step1:"1. Apri <strong>Chrome</strong> → <strong>trueachievements.com</strong>, accedi e collega il tuo Gamertag (sincronizzazione ~5 min)",
    xboxImportStep1Step2:"2. Profilo → scheda <strong>Games</strong> (elenco con il Gamerscore)",
    xboxImportStep1Step3:"3a. <strong>Con TA Pro</strong>: tocca Export → CSV → carica il file scaricato qui sopra. <br>3b. <strong>Senza Pro</strong>: tieni premuto un titolo → \"Seleziona tutto\" → \"Copia\"",
    xboxImportStep1Step4:"4. Torna qui → tieni premuto il campo qui sotto → <strong>Incolla</strong>",
    xboxImportStep1Step5:"5. Tocca Avanti. <em>💻 Computer: usa l'export CSV (con Pro) oppure Ctrl+S → carica l'HTML.</em>",
    xboxImportPasteLabel:"Incolla qui il contenuto CSV:",
    xboxImportPastePh:"Game,Platform,Gamerscore,Time Played,Completion\\n\"Halo Infinite\",Xbox Series X,1500,42h 30m,42%",
    xboxImportNextBtn:"Avanti →",
    xboxImportBackBtn:"← Indietro",
    xboxImportEmpty:"Nessun gioco trovato. Controlla il formato CSV.",
    xboxImportPreviewTitle:"Trovati {n} {gw}",
