    playniteImportRowTitle:"🎯 Importar do Playnite (recomendado)",
    playniteImportRowDesc:"Todas as plataformas em um arquivo JSON + seus status do Playnite mantidos 1:1",
    playniteImportTitle:"Importar do Playnite",
    playniteImportStep1Title:"Como funciona",
    playniteImportStep1Body:"O Playnite é um gerenciador de biblioteca gratuito que junta Steam/Epic/GOG/Xbox/PSN/Battle.net/Origin/Uplay em uma só biblioteca. Seus status (Beaten, Playing, Plan to Play, Abandoned) passam 1:1, sem adivinhação.",
    playniteImportStep1Step1:"1. Abra o <strong>Playnite</strong> (Windows). Não tem? <a href='https://playnite.link' target='_blank'>playnite.link</a> (grátis, código aberto)",
    playniteImportStep1Step2:"2. Instale a extensão <strong>\"Library Exporter\"</strong>: menu Add-ons → Browse → busque \"Library Exporter\" → Install",
    playniteImportStep1Step3:"3. Depois de instalar: menu <strong>Extensions</strong> → Library Exporter → escolha o formato <strong>JSON</strong>",
    playniteImportStep1Step4:"4. Salve o arquivo <code>.json</code> com toda a sua biblioteca",
    playniteImportStep1Step5:"5. Envie o arquivo abaixo e toque em Próximo. <em>📱 Pelo celular? Sincronize o arquivo pela nuvem (Drive, Dropbox), baixe e envie aqui.</em>",
    playniteImportPasteLabel:"Ou cole o conteúdo JSON aqui:",
    playniteImportPastePh:"[{\"Name\":\"The Witcher 3\",\"Source\":{\"Name\":\"Steam\"},\"Playtime\":360000,\"CompletionStatus\":{\"Name\":\"Beaten\"}},...]",
    playniteImportNextBtn:"Próximo →",
    playniteImportBackBtn:"← Voltar",
    playniteImportEmpty:"Nenhum jogo encontrado. Confira se o JSON é do Playnite Library Exporter.",
    playniteImportPreviewTitle:"{n} {gw} encontrados",
    playniteImportPreviewSub:"Status do Playnite (Beaten/Playing etc.) mapeados automaticamente. Toque em um selo de status para mudar.",
    playniteImportCommitBtn:"+ Adicionar selecionados ({n})",
    playniteImportSuccess:"✓ {n} {gw} importados do Playnite",
    playniteImportOpenSite:"Abrir playnite.link →",
    psnImportRowTitle:"📥 Importar do PSN-Profiles",
    psnImportRowDesc:"Carregue sua biblioteca da PSN pelo psnprofiles.com",
    psnImportTitle:"Importar do PSN-Profiles",
    psnImportStep1Title:"Como funciona",
    psnImportStep1Body:"O PSN-Profiles é um espelho público da sua biblioteca da PSN. Não há exportação CSV, então você vai copiar a tabela direto do celular.",
    psnImportStep1Step1:"1. Abra o <strong>Chrome</strong> e acesse <strong>psnprofiles.com</strong>, crie uma conta grátis (se não tiver) e vincule sua ID da PSN (sincronização ~5 min)",
    psnImportStep1Step2:"2. Vá direto para <strong>psnprofiles.com/SUA-ID-PSN/games</strong> (NÃO o perfil geral: a página <code>/games</code> tem uma tabela limpa, sem anúncios nem recomendações na lateral)",
    psnImportStep1Step3:"3. Role <strong>até o fim da tabela de jogos</strong> (para carregar todos) → toque e segure um título → <strong>\"Selecionar tudo\"</strong>. O leitor filtra automaticamente as seções \"Recommended/Sponsored\".",
    psnImportStep1Step4:"4. Toque em <strong>\"Copiar\"</strong> (o Chrome copia a tabela com tabulações entre as colunas, e o nosso leitor entende)",
    psnImportStep1Step5:"5. Volte aqui → toque e segure o campo abaixo → <strong>Colar</strong> → Próximo. <br><em>📱 iPhone/Safari? Funciona igual (o Safari copia uma célula por linha, o leitor entende). 💻 Computador? Ctrl+S na página de jogos → salvar como HTML → envie o arquivo acima.</em>",
    psnImportPasteLabel:"Cole aqui a tabela copiada do PSN-Profiles:",
    psnImportPastePh:"Game\\tPlatform\\tTrophies\\tHours\\tProgress\\nGod of War Ragnarök\\tPS5\\t36/36\\t18\\t100%",
    psnImportNextBtn:"Próximo →",
    psnImportBackBtn:"← Voltar",
    psnImportEmpty:"Nenhum jogo encontrado. Confira o formato do CSV.",
    psnImportPreviewTitle:"{n} {gw} encontrados",
    psnImportPreviewSub:"Buscando dados no RAWG (capas, gêneros). Desmarque os jogos que não quer importar.",
    psnImportMatching:"⏳ Buscando…",
    psnImportFound:"✓ Encontrado",
    psnImportNoMatch:"⚠️ Sem dados do RAWG: só o título será importado",
    psnImportDup:"↻ Já está na biblioteca",
    psnImportCommitBtn:"+ Adicionar selecionados ({n})",
    psnImportCommitting:"⏳ Adicionando…",
    psnImportSuccess:"✓ {n} {gw} importados do PSN-Profiles",
