    steamImportRowTitle:"⚙️ Importar da Steam",
    steamImportRowDesc:"Carregue sua biblioteca da Steam (colando do código-fonte da página)",
    steamImportTitle:"Importar da Steam",
    steamImportStep1Title:"Como funciona",
    steamImportStep1Body:"A Web API da Steam é bloqueada por CORS, então usamos o código-fonte do seu perfil público (a biblioteca precisa ser <strong>pública</strong>).",
    steamImportStep1Step1:"1. Abra o <strong>Chrome</strong> e digite na barra de endereço: <code>view-source:steamcommunity.com/id/SEU-ID/games?tab=all</code> (computador: basta Ctrl+U na página de jogos)",
    steamImportStep1Step2:"2. Depois de carregar, você verá o código HTML/JS bruto da página",
    steamImportStep1Step3:"3. Toque e segure o texto → toque em <strong>\"Localizar na página\"</strong> (menu de 3 pontos) → digite <strong>rgGames</strong>, ele vai até <code>var rgGames = [...]</code>",
    steamImportStep1Step4:"4. Toque e segure → \"Selecionar tudo\" → \"Copiar\" (o leitor extrai sozinho o JSON rgGames do HTML completo)",
    steamImportStep1Step5:"5. Cole no campo abaixo e toque em Próximo. <em>💻 Computador: Ctrl+U → Ctrl+F \"rgGames\" → selecione <code>[...]</code> → cole aqui.</em>",
    steamImportPasteLabel:"Cole o conteúdo de rgGames aqui:",
    steamImportPastePh:"[{\"appid\":1245620,\"name\":\"ELDEN RING\",\"playtime_forever\":5840},...]",
    steamImportNextBtn:"Próximo →",
    steamImportBackBtn:"← Voltar",
    steamImportEmpty:"Nenhum jogo encontrado. Confira o formato colado (JSON rgGames, array simples ou lista de títulos linha por linha).",
    steamImportPreviewTitle:"{n} {gw} encontrados",
    steamImportPreviewSub:"Buscando dados no RAWG (capas, gêneros). Desmarque os jogos que não quer importar.",
    steamImportCommitBtn:"+ Adicionar selecionados ({n})",
    steamImportSuccess:"✓ {n} {gw} importados da Steam",
    steamImportOpenSite:"Abrir steamcommunity.com →",
    xboxImportRowTitle:"🟢 Importar do Xbox (TrueAchievements)",
    xboxImportRowDesc:"Carregue sua biblioteca do Xbox pelo trueachievements.com",
    xboxImportTitle:"Importar do TrueAchievements",
    xboxImportStep1Title:"Como funciona",
    xboxImportStep1Body:"O TrueAchievements é um espelho público do Xbox. <strong>A exportação CSV exige o TA Pro</strong> (US$ 5/ano), mas quem usa a versão grátis pode simplesmente copiar a tabela do celular, e o nosso leitor entende.",
    xboxImportStep1Step1:"1. Abra o <strong>Chrome</strong> → <strong>trueachievements.com</strong>, entre e vincule sua Gamertag (sincronização ~5 min)",
    xboxImportStep1Step2:"2. Perfil → aba <strong>Games</strong> (lista com Gamerscore)",
    xboxImportStep1Step3:"3a. <strong>Com TA Pro</strong>: toque em Export → CSV → envie o arquivo baixado acima. <br>3b. <strong>Sem Pro</strong>: toque e segure um título → \"Selecionar tudo\" → \"Copiar\"",
    xboxImportStep1Step4:"4. Volte aqui → toque e segure o campo abaixo → <strong>Colar</strong>",
    xboxImportStep1Step5:"5. Toque em Próximo. <em>💻 Computador: use a exportação CSV (com Pro) ou Ctrl+S → envie o HTML.</em>",
    xboxImportPasteLabel:"Cole o conteúdo CSV aqui:",
